# parseDuration

`parseDuration(input)` takes a string and returns the total number of seconds as an integer.

- Input is one or more groups of `<integer><unit>`. Units are `h` (hours), `m` (minutes) and `s` (seconds).
- Units are case-insensitive: `2H` means the same as `2h`.
- Groups may come in any order, each unit at most once. Spaces between groups, and leading or trailing spaces, are ignored.
- A number without a unit is invalid.
- Throw an `Error` for any invalid input: empty string, unknown unit, a number without a unit, a repeated unit, negative or decimal numbers.
module.exports = function parseDuration(input) { throw new Error("not implemented"); };
#!/usr/bin/env node
// Scores src/duration.js against cases.json (same folder as this script).
// Usage: node score.js [repo]   (repo defaults to the parent of this folder)
"use strict";
const fs = require("fs");
const path = require("path");

const repo = process.argv[2] ? path.resolve(process.cwd(), process.argv[2]) : path.resolve(__dirname, "..");
const cases = JSON.parse(fs.readFileSync(path.join(__dirname, "cases.json"), "utf8"));
const label = process.env.SCORE_LABEL || "SCORE";

let parseDuration = null;
let loadError = null;
try {
  parseDuration = require(path.join(repo, "src", "duration.js"));
} catch (e) {
  loadError = e;
}

const show = (v) => (typeof v === "string" ? JSON.stringify(v) : String(v));
let passed = 0;
for (const c of cases) {
  const expected = c.throws ? "throws" : show(c.expected);
  let got;
  let ok = false;
  if (loadError) {
    got = "load error: " + loadError.message;
  } else {
    try {
      const r = parseDuration(c.input);
      got = show(r);
      ok = !c.throws && r === c.expected;
    } catch (e) {
      got = "throws (" + (e && e.message) + ")";
      ok = !!c.throws && e instanceof Error;
    }
  }
  if (ok) passed++;
  console.log(`${ok ? "PASS" : "FAIL"}  input=${JSON.stringify(c.input)}  expected=${expected}  got=${got}`);
}
console.log(`${label}: ${passed}/${cases.length}`);
eval
